#!/usr/bin/env python3
"""Render the measured results into Markdown and an offline listening worksheet."""
import csv,html,json,pathlib
root=pathlib.Path(__file__).resolve().parent
results=json.loads((root/'results.json').read_text());summary=json.loads((root/'summary.json').read_text());tests=json.loads((root/'tests.json').read_text());meta=json.loads((root/'run-metadata.json').read_text());reference=json.loads((root/'reference-metadata.json').read_text())
fmt=lambda n: f'{n:.2f}' if n is not None else 'N/A'
quote='I loved the output of the model. It felt like my voice itself.'
successful=[r for r in results if r['status']=='success']
emotion=next((r for r in successful if r['id']=='03_emotion'),None)
others=[r['quiet_frame_fraction_below_minus50dbfs'] for r in successful if r['id']!='03_emotion']
repeats=[r for r in successful if 'consistency_take' in r['id']]
lines=['# Local voice-cloning experiments on a 4 GB RTX 2050','',f"Run started: {meta['started_utc']}. Voice: Jivraj. Research status: **generation measured; stress-test listening review pending**.",'','## Why this experiment','', 'I wanted to find out whether a local voice-cloning model could reproduce my voice, how much hardware it needed, and where it might fail.', '', 'My initial comment, made before these stress tests:', '', '> '+quote, '', 'That comment applies to the earlier short clone. It is not a rating for the clips below.', '', '## Setup', '', '- App: VoiceStudio v0.5.6 Electron, with the local setup fixes described below.', '- Model: k2-fsa/OmniVoice, converted as Serveurperso/OmniVoice-GGUF; Q8_0 language model and tokenizer.', '- Runtime: omnivoice.cpp commit 886fc079838ca7400cb2b42b36e2a65aa1daabe8, compiled for CUDA sm_86.', '- Hardware: Intel Core i5-12450H, approximately 16 GB system RAM, NVIDIA RTX 2050 with 4,096 MiB VRAM.', f"- Reference: {reference['duration_seconds']:.2f} seconds, 24 kHz mono PCM16 WAV, with its exact transcript supplied.", '- Reference recording is not included. Generated clips, prompts, seeds, hashes, and reference metadata are included.', '- No model training or fine-tuning. All runs use the same saved voice reference.', '- One request at a time, with a one-second gap. Different explicit seeds are used for the three consistency takes.', '- Model files and app dependencies were already installed. Setup/download/compilation time is excluded.', '- The native runtime launches a fresh process and reloads weights for each request. The application and watermark dependency were already warmed.', '', '## Results', '', f"**{summary['successful']}/{summary['test_count']} HTTP requests succeeded.** Total generated audio: **{summary['total_audio_seconds']/60:.2f} minutes**. Sum of generation request wall times: **{summary['total_request_wall_seconds']/60:.2f} minutes**. This is one run per prompt, not a statistically stable benchmark.", '', '| Test / audio | Request time | Audio length | RTF | Peak total GPU VRAM | Peak native-process VRAM |', '|---|---:|---:|---:|---:|---:|']
for r in results:
 link=f"[{r['title']}]({r['audio_file']})" if r['status']=='success' else r['title']+' (failed)'
 lines.append(f"| {link} | {r['wall_seconds']:.2f} s | {fmt(r.get('duration_seconds'))} s | {fmt(r.get('real_time_factor'))} | {fmt(r.get('gpu_peak_total_used_mib'))} MiB | {fmt(r.get('gpu_peak_native_process_mib'))} MiB |")
lines+=['','RTF = request wall time / output duration. Below 1 means the complete request finished faster than the duration of its generated audio. It is not time-to-first-audio or proof of conversational latency.','',f"Highest sampled total GPU usage: **{summary['peak_total_gpu_memory_mib']:.0f} MiB ({summary['peak_total_gpu_memory_mib']/1024:.2f} GiB)**. Highest single native speech process: **{summary['peak_single_native_process_mib']:.0f} MiB ({summary['peak_single_native_process_mib']/1024:.2f} GiB)**.",'','## How VRAM and time were measured','','- NVIDIA telemetry sampled at a target interval of 200 ms; raw CSV files are included. A shorter allocation spike may be missed.', '- Total GPU memory includes every GPU application. Native-process VRAM is separately sampled for the omnivoice-tts process and includes CUDA context, weights and buffers.', '- Per-test baseline is the median GPU memory in the preceding 0.8 seconds, with a five-second fallback window. Peak above baseline is available in results.csv.', '- Timing begins immediately before the HTTP POST and ends when the full response body reaches the client. It includes server work, loading, postprocessing, watermarking and transfer; output-file writing/analysis is excluded.', '- No GPU-memory polling ran inside the synthesis process. An external nvidia-smi process collected the samples.', '- WAV decoding, RMS level, peak level and quiet frames were checked. These checks cannot establish intelligibility, likeness, emotion or correct pronunciation.', '', '## Automatic observations', '', f"All {len(successful)} successful responses decoded as WAV. Maximum observed clipped-sample fraction across clips: {max((r['clipped_sample_fraction'] for r in successful), default=0):.6f}. These waveform checks do not score content accuracy.", '', f"The emotion clip has about {emotion['quiet_frame_fraction_below_minus50dbfs']*100:.1f}% quiet 20 ms frames below -50 dBFS, versus about {min(others)*100:.1f}–{max(others)*100:.1f}% for the other clips. Its script contains an explicit hesitation; listening is needed to decide whether the pauses are natural or excessive." if emotion and others else 'Quiet-frame comparison unavailable.', '', f"The {len(repeats)} consistency takes last {min(r['duration_seconds'] for r in repeats):.2f}–{max(r['duration_seconds'] for r in repeats):.2f} seconds and took {min(r['wall_seconds'] for r in repeats):.2f}–{max(r['wall_seconds'] for r in repeats):.2f} seconds to generate. Duration and speed do not establish identity or pronunciation consistency." if repeats else 'No consistency takes available.', '', '## What to listen for / my comments', '', 'Open [the listening worksheet](index.html) in a browser for audio players, ratings and comments. It saves review drafts locally in that browser; use **Export my reviews** to save a JSON file for the repository. Until listening review is complete, ratings remain empty.', '']
for t in tests:
 lines += [f"### {t['title']}", '', f"[Listen](audio/{t['id']}.wav) · [Exact script](prompts/{t['id']}.txt)", '', t['listen_for'], '', '**My comment:** pending listening review.', '']
lines+=['## How much did we pay?', '', '| Item | Amount |', '|---|---:|', '| VoiceStudio software / Pro subscription | $0 |', '| Hosted inference / ElevenLabs API charges | $0 |', '| New hardware purchased for this experiment | $0 |', '| Electricity cost | Not measured / not allocated |', '', 'We used an existing laptop. “$0 paid in software/API fees” does not mean zero electricity, free hardware, or zero setup time.', '', f"The integral of sampled GPU-reported power during the request windows is approximately **{summary['gpu_reported_energy_estimate_wh']:.3f} Wh**. This is an estimate for the GPU component only, not wall power or total laptop energy. It excludes CPU, display, charger losses, setup, and idle gaps. No electricity tariff was supplied, so no electricity charge is claimed.", '', 'For a known tariff: estimated GPU-component cost = energy in Wh / 1,000 × tariff per kWh. This remains only part of the machine’s operating cost.', '', '### Hypothetical ElevenLabs comparison', '', f"The scripts total **{summary['total_requested_characters']:,} Unicode characters**, including repeated takes. At a model rate of one credit per character, that would be **{summary['total_requested_characters']:,} credits**. Allocating the normal Starter price ($6 / 30,000 credits) gives approximately **${summary['hypothetical_elevenlabs_at_1_credit_per_character']['allocated_allowance_usd']:.2f} of monthly allowance**. This is not an actual charge or a pay-as-you-go quote. Rates vary by model, and regeneration rules may differ.", '', 'The normal minimum monthly purchase for Instant Voice Cloning is Starter at $6 before taxes; offers or annual billing may change the purchase price. We bought no plan, sent no clips to ElevenLabs, and did not test its output. No quality-equivalence or demonstrated savings claim is made.', '', '[ElevenLabs pricing, checked 15 October 2026](https://elevenlabs.io/pricing).', '', '## Known setup friction and limitations', '', '- The shipped Linux AppImage omitted its native GGUF executable. It was built from the exact pinned source commit with CUDA support.', '- The setup gate required the full default model. A local catalog patch registers the downloaded quantized model instead.', '- A local constructor patch connects the saved quantization preference. Both patches are in patches/. They are setup changes, not a new trained model.', '- An MP3 reference was accepted by the UI but rejected by the native WAV reader. Converting the recording to WAV resolved that failure. The earlier failure and setup work are not included in the eight timed tests.', '- System memory was already under pressure and swap was nearly full. This is a real laptop session, not an otherwise-idle laboratory benchmark.', '- HTTP success and audio duration do not establish spoken-content correctness. Transcript accuracy, voice drift, and expressiveness remain pending listening review.', '- No statistical repetitions except the three consistency takes, whose seeds intentionally differ. They do not measure fixed-seed reproducibility.', '- No other models, quantization levels, GPUs or hosted providers were benchmarked.', '- Upstream OmniVoice weights carry non-commercial terms. A GGUF conversion or the app’s AGPL license does not remove upstream restrictions.', '', '## Reproduce', '', '1. Use VoiceStudio v0.5.6 with the pinned runtime and Q8 files listed in model-manifest.json; review patches/README.md.', '2. Create an authorized saved voice with a short PCM WAV and its exact transcript. The original reference is omitted, so exact replication of this speaker requires separately providing that recording.', '3. Copy run_experiment.py, analyse_telemetry.py, build_report.py, tests.json and reference-metadata.json to a fresh run folder with empty audio/ and prompts/ subfolders; install requests, numpy and psutil in your chosen Python environment.', '4. Save each test text under prompts/<id>.txt. Run the two telemetry commands below in separate terminals, then run the experiment. Stop telemetry after the last case.', '', '```sh', 'nvidia-smi --query-gpu=timestamp,index,name,memory.total,memory.used,utilization.gpu,power.draw --format=csv,noheader,nounits --loop-ms=200 --filename=gpu-samples.csv', 'nvidia-smi --query-compute-apps=timestamp,pid,process_name,used_gpu_memory --format=csv,noheader,nounits --loop-ms=200 --filename=gpu-process-samples.csv', 'python3 run_experiment.py --base-url http://127.0.0.1:3900 --profile-id YOUR_PROFILE_ID', 'python3 analyse_telemetry.py', 'python3 build_report.py', '```', '', 'Keep NVIDIA timestamps and Python request times in the same system timezone. The telemetry analyser interprets NVIDIA timestamps in the host’s local timezone.', '', '## Files', '', '- audio/: eight generated WAV clips.', '- prompts/: exact UTF-8 scripts and request bodies.', '- results.csv / results.json: per-test measurements and listening prompts.', '- summary.json / run-metadata.json / model-manifest.json: totals, environment and checksums.', '- gpu-samples.csv / gpu-process-samples.csv: raw GPU telemetry.', '- index.html: offline listening and review worksheet.', '- reviews-template.json: empty fields for per-clip human review.', '- patches/: local app setup patches and build notes.', '', '## Sources', '', '- [Original OmniVoice model and model terms](https://huggingface.co/k2-fsa/OmniVoice)', '- [GGUF conversion](https://huggingface.co/Serveurperso/OmniVoice-GGUF)', '- [Native runtime](https://github.com/ServeurpersoCom/omnivoice.cpp)', '- [VoiceStudio release v0.5.6](https://github.com/debpalash/VoiceStudio/releases/tag/v0.5.6)', '- [ElevenLabs pricing](https://elevenlabs.io/pricing)', '']
(root/'README.md').write_text('\n'.join(lines))
reviews={'initial_comment':quote,'initial_comment_scope':'Earlier short clone, before the stress-test run','reviews':[{'id':t['id'],'likeness_1_to_5':None,'content_accuracy_1_to_5':None,'naturalness_1_to_5':None,'comment':None,'reviewed':False} for t in tests]};(root/'reviews-template.json').write_text(json.dumps(reviews,ensure_ascii=False,indent=2)+'\n')
# Embed all text and metadata so the worksheet works from file:// without fetch.
data=json.dumps({'tests':tests,'results':results,'summary':summary,'initial_comment':quote},ensure_ascii=False).replace('</','<\\/')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Local voice-cloning research — Jivraj</title><link rel="icon" href="data:,"><style>
:root{color-scheme:light;font-family:system-ui,sans-serif;color:#202b3b;background:#f3f5f8}body{max-width:1050px;margin:40px auto;padding:0 22px}h1{font-size:34px;letter-spacing:-1px;margin-bottom:10px}.muted{color:#59677b}.summary{display:flex;flex-wrap:wrap;gap:12px;margin:24px 0}.stat{background:#172940;color:white;border-radius:12px;padding:18px;min-width:180px}.stat strong{display:block;font-size:27px}article{background:white;border:1px solid #dce2ea;border-radius:14px;padding:24px;margin:18px 0}h2{margin-top:0;font-size:21px}audio{width:100%;margin:12px 0}.metrics{display:flex;flex-wrap:wrap;gap:18px;font-size:14px}.script{white-space:pre-wrap;line-height:1.7}.ratings{display:flex;flex-wrap:wrap;gap:18px;margin:18px 0}select,textarea,button{font:inherit;padding:9px;border:1px solid #bdc8d6;border-radius:6px}label{display:block}select{display:block;margin-top:6px}textarea{box-sizing:border-box;width:100%;min-height:90px;margin-top:7px}button{background:#172940;color:white;cursor:pointer}.notice{background:#fff4d8;border-radius:9px;padding:16px;line-height:1.6}a{color:#1766a3}blockquote{border-left:3px solid #748da9;padding-left:16px}footer{margin:25px 0 45px;line-height:1.6}details{margin:14px 0}button:focus,select:focus,textarea:focus{outline:3px solid #6d9bc7;outline-offset:2px}</style>
<h1>Local voice-cloning research</h1><p class="muted">Jivraj · OmniVoice GGUF Q8 · RTX 2050 / 4 GB · 15 October 2026</p><p>Initial reaction, before these stress tests:</p><blockquote id="quote"></blockquote><div class="summary" id="summary"></div><p class="notice">Generation measurements are complete. Listening ratings are yours to fill in. A successful HTTP request is not a pronunciation or likeness score. VRAM peaks were sampled every 200 ms. Electricity cost was not measured.</p><p><a href="README.md">Research report</a> · <a href="results.csv">Measurements CSV</a> · <a href="results.json">Raw results JSON</a></p><p><button id="export">Export my reviews</button> <span id="save-status" class="muted">Drafts save in this browser. Export a JSON file to include them on GitHub.</span></p><main id="cases"></main><footer>RTF = request time / audio length; below 1 means faster than real time. Total VRAM includes other GPU processes. Native-process VRAM includes CUDA context and buffers. The estimated ElevenLabs allowance is a hypothetical allocation, not a bill or a quality comparison.</footer><script type="application/json" id="data">__DATA__</script><script>
const d=JSON.parse(document.getElementById('data').textContent), key='jivraj-voice-research-'+d.results[0].start_utc;let reviews={};try{reviews=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){}const el=(tag,text)=>{const x=document.createElement(tag);if(text!==undefined)x.textContent=text;return x};document.getElementById('quote').textContent=d.initial_comment;
const s=d.summary;for(const [value,label]of [[s.successful+'/'+s.test_count,'successful generations'],[(s.total_audio_seconds/60).toFixed(2)+' min','generated audio'],[(s.peak_total_gpu_memory_mib/1024).toFixed(2)+' GiB','peak total GPU usage'],['$0','software / API fees paid']]){const box=el('div');box.className='stat';box.append(el('strong',value),el('span',label));document.getElementById('summary').append(box)}
function save(){try{localStorage.setItem(key,JSON.stringify(reviews));document.getElementById('save-status').textContent='Draft saved locally. Export to keep a review file for GitHub.'}catch(e){document.getElementById('save-status').textContent='Local storage unavailable. Use Export my reviews before closing.'}}
for(const t of d.tests){const r=d.results.find(x=>x.id===t.id),a=el('article');a.append(el('h2',t.title));const m=el('div');m.className='metrics';for(const text of [r.status,(r.wall_seconds||0).toFixed(2)+' s request',(r.duration_seconds||0).toFixed(2)+' s audio','RTF '+(r.real_time_factor||0).toFixed(3),(r.gpu_peak_total_used_mib||0)+' MiB peak total VRAM',(r.gpu_peak_native_process_mib||0)+' MiB native process'])m.append(el('span',text));a.append(m);if(r.status==='success'){const player=el('audio');player.controls=true;player.preload='none';player.src=r.audio_file;a.append(player)}const details=el('details');details.append(el('summary','Show exact script'));const p=el('p',t.text);p.className='script';details.append(p);a.append(details,el('p',t.listen_for));reviews[t.id]??={id:t.id,likeness_1_to_5:null,content_accuracy_1_to_5:null,naturalness_1_to_5:null,comment:'',reviewed:false};const review=reviews[t.id],ratings=el('div');ratings.className='ratings';for(const[field,label]of [['likeness_1_to_5','Voice likeness'],['content_accuracy_1_to_5','Content accuracy'],['naturalness_1_to_5','Naturalness']]){const l=el('label',label),select=el('select');select.append(new Option('Not reviewed',''));for(let i=1;i<=5;i++)select.append(new Option(i+(i===1?' — poor':i===5?' — excellent':''),String(i)));select.value=review[field]===null?'':String(review[field]);select.onchange=()=>{review[field]=select.value?Number(select.value):null;review.reviewed=['likeness_1_to_5','content_accuracy_1_to_5','naturalness_1_to_5'].some(k=>review[k]!==null)||!!review.comment;save()};l.append(select);ratings.append(l)}a.append(ratings);const l=el('label','My comments'),textarea=el('textarea');textarea.placeholder='What sounded like you? Which word, pause or emotion failed? Add timestamps.';textarea.value=review.comment;textarea.oninput=()=>{review.comment=textarea.value;review.reviewed=!!review.comment||['likeness_1_to_5','content_accuracy_1_to_5','naturalness_1_to_5'].some(k=>review[k]!==null);save()};l.append(textarea);a.append(l);document.getElementById('cases').append(a)}
document.getElementById('export').onclick=()=>{const payload={exported_utc:new Date().toISOString(),initial_comment:d.initial_comment,initial_comment_scope:'Earlier short clone, before the stress-test run',reviews:Object.values(reviews)},url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})),link=el('a');link.href=url;link.download='jivraj-listening-reviews.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
</script></html>'''
(root/'index.html').write_text(page.replace('__DATA__',data))
print('Built README.md, index.html, reviews-template.json')
